# Complete self-contained solution
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from itertools import combinations

N = 14
MIN_EDGES = 18
MIN_GIRTH = 7
K = 3

all_edges = [(u, v) for u in range(N) for v in range(u+1, N)]
E = len(all_edges)
edge_idx = {e: i for i, e in enumerate(all_edges)}

def evar(u, v):
    e = (min(u,v), max(u,v))
    return edge_idx[e] + 1

def cvar(v, k):
    return E + v*K + k + 1

clauses = []

# 3-coloring
for v in range(N):
    clauses.append([cvar(v, k) for k in range(K)])
    for k1 in range(K):
        for k2 in range(k1+1, K):
            clauses.append([-cvar(v, k1), -cvar(v, k2)])

for u, v in all_edges:
    for k in range(K):
        clauses.append([-evar(u,v), -cvar(u,k), -cvar(v,k)])

# Girth >= 7: forbid cycles of length 3,4,5,6
# Length 3
for a,b,c in combinations(range(N), 3):
    clauses.append([-evar(a,b), -evar(b,c), -evar(a,c)])

# Length 4
seen4 = set()
for a,b,c,d in [(a,b,c,d) for a in range(N) for b in range(N) 
                 for c in range(N) for d in range(N)
                 if len({a,b,c,d})==4]:
    es = frozenset([(min(a,b),max(a,b)),(min(b,c),max(b,c)),
                    (min(c,d),max(c,d)),(min(d,a),max(d,a))])
    if len(es)==4 and es not in seen4:
        seen4.add(es)
        clauses.append([-evar(a,b),-evar(b,c),-evar(c,d),-evar(d,a)])

print(f"After 4-cycles: {len(clauses)}, unique: {len(seen4)}")

# Length 5
seen5 = set()
for a in range(N):
  for b in range(N):
    if b==a: continue
    for c in range(N):
      if c in (a,b): continue
      for d in range(N):
        if d in (a,b,c): continue
        for e in range(N):
          if e in (a,b,c,d): continue
          es = frozenset([(min(a,b),max(a,b)),(min(b,c),max(b,c)),
                          (min(c,d),max(c,d)),(min(d,e),max(d,e)),
                          (min(e,a),max(e,a))])
          if len(es)==5 and es not in seen5:
            seen5.add(es)
            clauses.append([-evar(a,b),-evar(b,c),-evar(c,d),-evar(d,e),-evar(e,a)])

print(f"After 5-cycles: {len(clauses)}, unique: {len(seen5)}")
